<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Composition with Red, Blue and Yellow — Mondrian, 1930</title>
<meta name="description" content="The story of Piet Mondrian's Composition with Red, Blue and Yellow (1930) and the De Stijl movement.">
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Jost:ital,wght@0,400;0,500;0,700;1,400&display=swap" rel="stylesheet">
<style>
  :root {
    --red: #d40119;
    --blue: #1b3fa0;
    --yellow: #f7c800;
    --ink: #0a0a0a;
    --paper: #ffffff;
    --line: 8px;
  }
  * { margin: 0; padding: 0; box-sizing: border-box; }
  html { scroll-behavior: smooth; }
  body {
    font-family: "Jost", "Futura", "Century Gothic", sans-serif;
    background: var(--paper);
    color: var(--ink);
    line-height: 1.55;
  }
  .wrap { max-width: 1120px; margin: 0 auto; padding: 0 24px; }

  /* Top rule: a Mondrian strip */
  .strip { display: flex; height: 18px; border-bottom: var(--line) solid var(--ink); }
  .strip .r { background: var(--red); flex: 5; }
  .strip .w { background: var(--paper); flex: 2; }
  .strip .b { background: var(--blue); flex: 1.4; }
  .strip .y { background: var(--yellow); flex: 1; }

  /* Hero */
  .hero {
    display: grid;
    grid-template-columns: 1.15fr 0.85fr;
    gap: 0;
    border-bottom: var(--line) solid var(--ink);
  }
  .hero-copy { padding: 72px 48px 64px 24px; align-self: center; }
  .kicker {
    display: inline-block;
    font-weight: 700;
    font-size: 0.8rem;
    letter-spacing: 0.22em;
    text-transform: uppercase;
    background: var(--ink);
    color: var(--paper);
    padding: 6px 12px;
    margin-bottom: 24px;
  }
  h1 {
    font-size: clamp(2.2rem, 5.2vw, 4rem);
    font-weight: 700;
    line-height: 1.04;
    letter-spacing: -0.01em;
    text-transform: uppercase;
  }
  h1 .red { color: var(--red); }
  h1 .blue { color: var(--blue); }
  h1 .yellow { color: #c79b00; }
  .lede {
    margin-top: 22px;
    font-size: 1.15rem;
    max-width: 46ch;
  }
  .cta {
    display: inline-block;
    margin-top: 34px;
    background: var(--ink);
    color: var(--paper);
    font-family: inherit;
    font-weight: 700;
    font-size: 1rem;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    text-decoration: none;
    padding: 16px 28px;
    border: var(--line) solid var(--ink);
    box-shadow: 10px 10px 0 var(--yellow);
    transition: transform 0.12s ease, box-shadow 0.12s ease;
  }
  .cta:hover, .cta:focus-visible {
    transform: translate(5px, 5px);
    box-shadow: 5px 5px 0 var(--red);
  }
  .hero-art {
    border-left: var(--line) solid var(--ink);
    background: var(--ink);
    padding: var(--line);
    display: grid;
    grid-template-columns: 32% 44% 24%;
    grid-template-rows: 58% 22% 20%;
    gap: var(--line);
    min-height: 420px;
  }
  .hero-art div { background: var(--paper); }
  .hero-art .red    { grid-area: 1 / 2 / 2 / 4; background: var(--red); }
  .hero-art .blue   { grid-area: 2 / 1 / 4 / 2; background: var(--blue); }
  .hero-art .yellow { grid-area: 3 / 3 / 4 / 4; background: var(--yellow); }

  /* Facts grid */
  .facts {
    display: grid;
    grid-template-columns: repeat(6, 1fr);
    background: var(--ink);
    gap: var(--line);
    padding: var(--line);
  }
  .card {
    background: var(--paper);
    padding: 36px 32px 40px;
    position: relative;
  }
  .card .tag {
    display: inline-block;
    width: 22px; height: 22px;
    margin-bottom: 18px;
    border: 4px solid var(--ink);
  }
  .tag.red { background: var(--red); }
  .tag.blue { background: var(--blue); }
  .tag.yellow { background: var(--yellow); }
  .card h2 {
    font-size: 1.35rem;
    text-transform: uppercase;
    letter-spacing: 0.02em;
    margin-bottom: 12px;
  }
  .card p { font-size: 1rem; }
  .card p + p { margin-top: 12px; }
